// shop/cart.bynk
commons shop.cart

uses bynk.locale
uses shop.messages

fn banner(tag: LocaleTag, name: String) -> String {
  render(tag, message("cart.greeting"))     // ✗ `bynk.locale`'s `render`: it returns the code
  greet(tag, name)                           // ✓ call what shop.messages exports
}
